/// Definition of rounding modes (DON'T USE MPFR_RNDNA!).
/// Warning! Changing the contents of this enum should be seen as an
/// interface change since the old and the new types are not compatible
/// (the integer type compatible with the enumerated type can even change,
/// see ISO C99, 6.7.2.2#4), and in Makefile.am, AGE should be set to 0.
///
/// MPFR_RNDU must appear just before MPFR_RNDD (see
/// MPFR_IS_RNDUTEST_OR_RNDDNOTTEST in mpfr-impl.h).
///
/// If you change the order of the rounding modes, please update the routines
/// in texceptions.c which assume 0=RNDN, 1=RNDZ, 2=RNDU, 3=RNDD, 4=RNDA.
enum mpfr_rnd_t {
  /// round to nearest, with ties to even
  MPFR_RNDN(0),

  /// round toward zero
  MPFR_RNDZ(1),

  /// round toward +Inf
  MPFR_RNDU(2),

  /// round toward -Inf
  MPFR_RNDD(3),

  /// round away from zero
  MPFR_RNDA(4),

  /// faithful rounding
  MPFR_RNDF(5),

  /// round to nearest, with ties away from zero (mpfr_round)
  MPFR_RNDNA(-1);

  final int value;
  const mpfr_rnd_t(this.value);

  static mpfr_rnd_t fromValue(int value) => switch (value) {
    0 => MPFR_RNDN,
    1 => MPFR_RNDZ,
    2 => MPFR_RNDU,
    3 => MPFR_RNDD,
    4 => MPFR_RNDA,
    5 => MPFR_RNDF,
    -1 => MPFR_RNDNA,
    _ => throw ArgumentError('Unknown value for mpfr_rnd_t: $value'),
  };
}

